<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {createSupplier,getSupplierHistory,getSuppliersPage,type Supplier,type SupplierHistory} from '@/services/business'
import {useAuthStore} from '@/stores/auth'
const auth=useAuthStore(),items=ref<Supplier[]>([]),search=ref(''),error=ref(''),notice=ref(''),saving=ref(false),page=ref(0),totalPages=ref(0)
const form=reactive({supplierCode:'',name:'',contactName:'',phone:'',email:'',address:'',status:'ACTIVE'})
const history=ref<SupplierHistory>()
async function load(reset=false){if(reset)page.value=0;error.value='';try{const result=await getSuppliersPage(search.value,page.value);items.value=result.items;totalPages.value=result.totalPages}catch{error.value='Không thể tải nhà cung cấp.'}}
function move(delta:number){page.value+=delta;void load()}
async function showHistory(id:string){try{history.value=await getSupplierHistory(id)}catch{error.value='Không thể tải lịch sử nhập hàng.'}}
async function create(){saving.value=true;error.value='';try{const value=await createSupplier(form);notice.value=`Đã tạo nhà cung cấp ${value.name}.`;Object.assign(form,{supplierCode:'',name:'',contactName:'',phone:'',email:'',address:'',status:'ACTIVE'});await load()}catch{error.value='Không thể tạo nhà cung cấp. Kiểm tra mã và email.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><section class="p-6 lg:p-8"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold text-cyan-700">Danh mục nhập hàng</p><h2 class="text-3xl font-bold">Nhà cung cấp</h2></div><form class="flex gap-2" @submit.prevent="load(true)"><input v-model.trim="search" class="rounded-lg border px-3 py-2" placeholder="Mã hoặc tên"><button class="rounded-lg bg-slate-900 px-4 text-white">Tìm</button></form></div><p v-if="error" class="mt-4 rounded-lg bg-red-50 p-3 text-red-800">{{error}}</p><p v-if="notice" class="mt-4 rounded-lg bg-emerald-50 p-3 text-emerald-800">{{notice}}</p><form v-if="auth.hasPermission('supplier.manage')" class="mt-6 grid gap-3 rounded-xl border bg-white p-4 md:grid-cols-3" @submit.prevent="create"><input v-model.trim="form.supplierCode" required maxlength="50" class="rounded-lg border p-2" placeholder="Mã nhà cung cấp"><input v-model.trim="form.name" required maxlength="200" class="rounded-lg border p-2" placeholder="Tên"><input v-model.trim="form.contactName" maxlength="200" class="rounded-lg border p-2" placeholder="Người liên hệ"><input v-model.trim="form.phone" maxlength="30" class="rounded-lg border p-2" placeholder="Điện thoại"><input v-model.trim="form.email" type="email" maxlength="254" class="rounded-lg border p-2" placeholder="Email"><input v-model.trim="form.address" maxlength="500" class="rounded-lg border p-2" placeholder="Địa chỉ"><button :disabled="saving" class="rounded-lg bg-cyan-700 px-4 py-2 text-white md:col-span-3">{{saving?'Đang lưu…':'Thêm nhà cung cấp'}}</button></form><div v-if="history" class="mt-6 rounded-xl border bg-white p-5"><div class="flex justify-between"><div><h3 class="font-bold">Lịch sử nhập: {{history.supplier.name}}</h3><p class="text-sm text-slate-500">{{history.totalPurchaseOrders}} PO · đã thực nhập {{Number(history.receivedValue).toLocaleString()}} VND</p></div><button class="text-sm text-slate-500" @click="history=undefined">Đóng</button></div><div class="mt-3 divide-y"><p v-for="purchase in history.purchases" :key="purchase.id" class="flex justify-between py-2 text-sm"><span>{{purchase.poNumber}} · {{purchase.status}} · {{purchase.warehouseName}}</span><b>{{Number(purchase.total).toLocaleString()}} {{purchase.currency}}</b></p><p v-if="!history.purchases.length" class="py-3 text-sm text-slate-400">Chưa có đơn nhập hàng.</p></div></div><div class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Mã</th><th class="p-4">Tên</th><th class="p-4">Người liên hệ</th><th class="p-4">Điện thoại / email</th><th class="p-4">Trạng thái</th></tr></thead><tbody class="divide-y"><tr v-for="item in items" :key="item.id"><td class="p-4 font-mono">{{item.supplierCode}}</td><td class="p-4 font-semibold"><button class="text-left text-cyan-800 hover:underline" @click="showHistory(item.id)">{{item.name}}</button></td><td class="p-4">{{item.contactName||'—'}}</td><td class="p-4">{{item.phone||'—'}}<br><span class="text-xs text-slate-500">{{item.email}}</span></td><td class="p-4"><StatusBadge :value="item.status" /></td></tr><tr v-if="!items.length"><td colspan="5" class="p-8 text-center text-slate-400">Chưa có nhà cung cấp.</td></tr></tbody></table></div><div v-if="totalPages>1" class="mt-4 flex justify-end gap-3"><button :disabled="page===0" class="rounded border px-3 py-2 disabled:opacity-40" @click="move(-1)">Trước</button><span class="py-2">Trang {{page+1}} / {{totalPages}}</span><button :disabled="page+1>=totalPages" class="rounded border px-3 py-2 disabled:opacity-40" @click="move(1)">Sau</button></div></section></template>
